		pongActor pong;
	}

	statevars {
		byte id;
		string tmp;
	}

	constructor(pongActor p, byte i) {
		pong = p;
		id = i;
	}

	msghandler start() {
		tmp = "ping-";
		tmp = tmp + id;
		pong.msg(tmp);
	}

